gen en afgunst aan het licht. Collega’s en bestuurders reageren vanuit hun eigen belangen, terwijl de gelauwerde onderzoeker steeds minder reden tot vreugde heeft. Hermans onderzoekt in deze satirische roman hoe aanzien, rivaliteit en macht het academische bestaan beheersen.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/124271/onder-professoren.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789403187716","key":{"isbn_13":"9789403187716"},"before":null,"after":{"work_id":1014,"title":"Au pair","isbn_13":"9789403187716","isbn_10":"9403187719","language":"nld","publisher":"Bezige Bij b.v., Uitgeverij De","open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789403187716","key":{"edition_id":"@edition:9789403187716"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-004-20261031","evidence":[{"url":"https://metadata.isbn.nl/253281/au-pair.html","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://metadata.isbn.nl/253281/au-pair.html","checkedAt":"2026-10-31T20:11:51.383Z","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence","sha256":"f25d294c760cf710538157411ea6dfc0b42d04858ba14e3b7c67e4e31f6cd399"},{"url":"https://metadata.isbn.nl/ie_fcache/0000579736_Au_pair_0_0.jpg","checkedAt":"2026-10-31T20:47:19.595Z","http":200,"sha256":"f69fba6f8e39f24a5ee9f42590e8db36fbf84f4fc8e542f83aafc90dc6ee822e","bytes":205954,"fact":"Full source image decoded and inspected: matching title/author and exact edition source. Language established bibliographically, never from jacket alone."},{"reviewNote":"Choose verified2022 Dutch paperback9789403187716, not existing2011 ebook9789023467069. Spelling Fredrik in one source is not a second author identity."}],"edition_id":"@editio