n.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/253281/au-pair.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789025470142","key":{"id":1059},"before":{"id":1059,"title":"Mijn lieve gunsteling","isbn_10":null,"isbn_13":"9789025470142","work_id":1059,"language":null,"publisher":"Uitgeverij Atlas Contact","created_at":"2026-09-03T19:08:05.598672+00:00","open_library_edition_id":"OL31860712M"},"after":{"id":1059,"title":"Mijn lieve gunsteling","isbn_10":null,"isbn_13":"9789025470142","work_id":1059,"language":"nld","publisher":"Uitgeverij Atlas Contact","created_at":"2026-09-03T19:08:05.598672+00:00","open_library_edition_id":"OL31860712M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789025470142","key":{"edition_id":1059},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-004-20261031","evidence":[{"url":"https://www.atlascontact.nl/boek/mijn-lieve-gunsteling-hardback/","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://metadata.isbn.nl/1389076/mijn-lieve-gunsteling.html","checkedAt":"2026-10-31T20:11:53.565Z","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence","sha256":"aac635c6508ba4a73dd4ec695036461c7a3f80b6f5e545ebcbb6bb422c2726dc"},{"url":"https://metadata.isbn.nl/ie_fcache/0000374619_Mijn_lieve_gunsteling_0_0.jpg","checkedAt":"2026-10-31T20:22:21.553Z","http":200,"sha256":"c01b76fc40d4006208869fb3b3fb22778b3db0316abd57b49668da740f9da27e","bytes":163982,"fact":"Full source image decoded and inspected: matching title/author and exact edition source. Language established bibliographically, never from jacket alone."},{"reviewNote":"Lucas/Marieke Lucas refer to the same author; preserve existing authorID/name. Adult-veterinarian/minor relationship explicitly described as