s van de volwassen man onderzoekt Rijneveld hoe verlies, identiteit en grensoverschrijdend verlangen met elkaar verknoopt raken. Het platteland biedt daarbij geen bescherming tegen de dreiging die dichtbij ontstaat.","source_type":"official_publisher","source_name":"www.atlascontact.nl","source_url":"https://www.atlascontact.nl/boek/mijn-lieve-gunsteling-hardback/","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789029518215","key":{"id":1064},"before":{"id":1064,"title":"Een vlucht regenwulpen","isbn_10":null,"isbn_13":"9789029518215","work_id":1064,"language":null,"publisher":"De Arbeiderspers","created_at":"2026-09-03T19:08:17.534026+00:00","open_library_edition_id":"OL24922333M"},"after":{"id":1064,"title":"Een vlucht regenwulpen","isbn_10":null,"isbn_13":"9789029518215","work_id":1064,"language":"nld","publisher":"De Arbeiderspers","created_at":"2026-09-03T19:08:17.534026+00:00","open_library_edition_id":"OL24922333M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789029518215","key":{"edition_id":1064},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-004-20261031","evidence":[{"url":"https://www.singeluitgeverijen.nl/de-arbeiderspers/boek/een-vlucht-regenwulpen/","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://openlibrary.org/books/OL24922333M","checkedAt":"2026-10-31","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence"},{"url":"https://www.deslegte.com/een-vlucht-regenwulpen-114959/","checkedAt":"2026-10-31","fact":"Independent author, format, narrative or edition-identity corroboration"},{"url":"https://covers.openlibrary.org/b/id/6868785-L.jpg?default=false","checkedAt":"2026-10-31T20:26:49.849Z","http":200,"sha256":"a212513e1692d99d0156198b48e8ec328b0e284d1e936fae3683bf16ee3f0d73","bytes":34603,"fact":"Full source imag