ndere mensen. In deze roman onderzoekt Maarten ’t Hart hoe isolement, angst en dwangmatige gedachten een leven kunnen bepalen. Daartegenover staan een sterke opmerkingsgave en een innige belangstelling voor de natuur. De kleine wereld waarin het verhaal wortelt, wordt zo een plaats waar verlangen naar nabijheid en behoefte aan bescherming botsen.","source_type":"official_publisher","source_name":"www.singeluitgeverijen.nl","source_url":"https://www.singeluitgeverijen.nl/de-arbeiderspers/boek/een-vlucht-regenwulpen/","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789041409713","key":{"id":1073},"before":{"id":1073,"title":"De verbouwing","isbn_10":null,"isbn_13":"9789041409713","work_id":1073,"language":null,"publisher":"Anthos","created_at":"2026-09-03T19:08:36.766062+00:00","open_library_edition_id":"OL25945566M"},"after":{"id":1073,"title":"De verbouwing","isbn_10":null,"isbn_13":"9789041409713","work_id":1073,"language":"nld","publisher":"Anthos","created_at":"2026-09-03T19:08:36.766062+00:00","open_library_edition_id":"OL25945566M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789041409713","key":{"edition_id":1073},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-004-20261031","evidence":[{"url":"https://metadata.isbn.nl/69201/de-verbouwing.html","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://metadata.isbn.nl/69201/de-verbouwing.html","checkedAt":"2026-10-31T20:11:55.699Z","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence","sha256":"d3b0def0e8c8f2cf31790c9434a05ff62cc5c0b795ade49a85ce95e64199603a"},{"url":"https://metadata.isbn.nl/ie_fcache/0000074791_De_verbouwing_0_0.jpg","checkedAt":"2026-10-31T20:22:23.351Z","http":200,"sha256":"86e3f44fc18bd6c4804072b414e1af3f73c5a7b79765b88c102eb4b7e902972e","bytes":125159,"fact":