ool en probeert een goede band met haar leerlingen te onderhouden. Een bedreiging tijdens een les tast dat vertrouwen aan. Wanneer het gevaar aanhoudt, moet ze afwegen hoe ver haar verantwoordelijkheid tegenover de school reikt. De thriller onderzoekt hoe angst een vertrouwde omgeving verandert en hoe moeilijk het wordt te bepalen op wie zij kan rekenen.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/35883/schaduwzuster.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789044507881","key":{"id":1096},"before":{"id":1096,"title":"De macht van meneer Miller","isbn_10":null,"isbn_13":"9789044507881","work_id":1096,"language":null,"publisher":"De Geus","created_at":"2026-09-03T19:09:33.879916+00:00","open_library_edition_id":"OL35330073M"},"after":{"id":1096,"title":"De macht van meneer Miller","isbn_10":null,"isbn_13":"9789044507881","work_id":1096,"language":"nld","publisher":"De Geus","created_at":"2026-09-03T19:09:33.879916+00:00","open_library_edition_id":"OL35330073M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789044507881","key":{"edition_id":1096},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-004-20261031","evidence":[{"url":"https://books.google.com/books?id=Afo4DwAAQBAJ","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://openlibrary.org/books/OL35330073M","checkedAt":"2026-10-31","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence"},{"url":"https://deboekenplank.nl/naslag/aut/t/tex_c.htm","checkedAt":"2026-10-31","fact":"Independent author, format, narrative or edition-identity corroboration"},{"url":"https://covers.openlibrary.org/b/id/12148286-L.jpg?default=false","checkedAt":"2026-10-31T20:26:56.928Z","http":200,"sha256":"9c744308fcb9a17985ae86cfa6459d4ab317a3