ziet zijn succesvolle bestaan kantelen na een ontregelende ontmoeting met zijn broer. Op kantoor probeert hij te voorkomen dat hij buitenspel wordt gezet, maar juist daar is hij getuige van iets gevaarlijks. Tijdens zijn vlucht duikt telkens de naam Miller op. De thriller volgt hoe Bellicher tegenover tegenstanders komt te staan die veel meer over hem lijken te weten dan hij over hen.","source_type":"official_publisher","source_name":"Publisher-supplied Google Books","source_url":"https://books.google.com/books?id=Afo4DwAAQBAJ","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789056376871","key":{"isbn_13":"9789056376871"},"before":null,"after":{"work_id":1117,"title":"Hasse Simonsdochter","isbn_13":"9789056376871","isbn_10":"905637687X","language":"nld","publisher":"Lemniscaat B.V., Uitgeverij","open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789056376871","key":{"edition_id":"@edition:9789056376871"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-004-20261031","evidence":[{"url":"https://lemniscaat.nl/index.php/boeken/hasse-simonsdochter","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://metadata.isbn.nl/1184272/hasse-simonsdochter.html","checkedAt":"2026-10-31T20:32:26.932Z","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence","sha256":"a10b79133e62f3f0bc26307572c2f3764278b5a8ce7a5d3ab623a708cdf9847f"},{"url":"https://metadata.isbn.nl/ie_fcache/0000468094_Hasse_Simonsdochter_0_0.jpg","checkedAt":"2026-10-31T20:34:02.394Z","http":200,"sha256":"b6356b7a007d6bf04eccf485044963a95faddf644463191ae04a78cd764ab5d3","bytes":118817,"fact":"Full source image decoded and inspected: matching title/author and exact edition source. Language established bibliographically, never from jacket alone."},{"reviewNote":"R