ee en neemt ze deel aan hun gevaarlijke ondernemingen. Wanneer de groep wordt ingesloten, komt haar vrijheid opnieuw onder druk te staan. Thea Beckman verbindt Hasses eigenzinnige levenskeuze met het geweld van een historische machtsstrijd.","source_type":"official_publisher","source_name":"lemniscaat.nl","source_url":"https://lemniscaat.nl/index.php/boeken/hasse-simonsdochter","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789064940019","key":{"id":1127},"before":{"id":1127,"title":"Paniek","isbn_10":null,"isbn_13":"9789064940019","work_id":1127,"language":null,"publisher":"Prometheus Lucifer","created_at":"2026-09-03T19:10:52.287962+00:00","open_library_edition_id":"OL35329990M"},"after":{"id":1127,"title":"Paniek","isbn_10":null,"isbn_13":"9789064940019","work_id":1127,"language":"nld","publisher":"Prometheus Lucifer","created_at":"2026-09-03T19:10:52.287962+00:00","open_library_edition_id":"OL35329990M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789064940019","key":{"edition_id":1127},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-004-20261031","evidence":[{"url":"https://www.carryslee.nl/boek/1907/carry-slee-paniek.html","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://openlibrary.org/books/OL35329990M","checkedAt":"2026-10-31","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence"},{"url":"https://www.bibliotheek.nl/catalogus/titel.435420011.html/paniek/","checkedAt":"2026-10-31","fact":"Independent author, format, narrative or edition-identity corroboration"},{"url":"https://www.bol.com/nl/nl/p/paniek/1001004000112307/","checkedAt":"2026-10-31","fact":"Independent author, format, narrative or edition-identity corroboration"},{"url":"https://covers.openlibrary.org/b/id/12148169-L.jpg?default=false","checkedAt":"2026-10-